syntax:
C++ syntax illustrating RVO/NRVO and their potential failure:

```c++
class MyClass {
public:
    MyClass(int val) : value(val) { std::cout << "Constructor called\n"; }
    MyClass(const MyClass& other) : value(other.value) { std::cout << "Copy constructor called\n"; }
    ~MyClass() { std::cout << "Destructor called\n"; }
    int value;
};

MyClass createMyClass(int val) {
    MyClass obj(val); // NRVO opportunity here
    return obj;      // NRVO or RVO opportunity here
}

MyClass createMyClass2(int val) {
    MyClass obj(val);
    MyClass obj2 = obj; // Prevents NRVO, might still enable RVO.
    return obj; 
}

MyClass createMyClass3(int val) { 
    return MyClass(val); // RVO opportunity
}

int main() {
    MyClass c1 = createMyClass(10);
    MyClass c2 = createMyClass2(20);
    MyClass c3 = createMyClass3(30);
    return 0;
}
```

